def _matches(prediction, ground_truth):
    if is_equiv(prediction, ground_truth):
        return True
    return _canonical(prediction) == _canonical(ground_truth)


def compute_score(data_source, solution_str, ground_truth, extra_info=None):
    if not data_source.startswith("train-math-"):
        raise ValueError(f"Expected a Skywork math row, got {data_source!r}")
    answers = json.loads(ground_truth)
    if not isinstance(answers, list) or not answers or not all(isinstance(answer, str) for answer in answers):
        raise ValueError(f"Expected nonempty Skywork answer list, got {ground_truth!r}")
    # Nemotron-brorl ends each solution with "**Final Answer:** $\\boxed{X}$" (and
    # repeats the box).  The verdict lives in the last boxed expression, so extract
    # the answer from the full response rather than scanning a truncated tail for an
    # "Answer:" marker the model never emits.  Reward scale unchanged: +1/-1.
    boxed = last_boxed_only_string(solution_str)
    pred = remove_boxed(boxed) if boxed is not None else "[INVALID]"
    for answer in answers:
        if boxed is not None and _matches(pred, answer):
            return {"score": 1.0, "acc": True, "pred": pred}
    return {"score": -1.0, "acc": False, "pred": pred}
